import {renderOffline} from './encoder.js';
'use strict';
const $ = id => document.getElementById(id);
const canvas = $('canvas'), ctx = canvas.getContext('2d', {alpha:false});
const settings = ['duration','ratio','quality','theme','motion','captions','fileformat'];
const grades = {forest:'contrast(1.06) saturate(1.04)',ocean:'contrast(1.08) saturate(.85)',sunset:'contrast(1.04) saturate(1.16) sepia(.18)',mono:'grayscale(1) contrast(1.1)'};
let scenes=[], photos=[], photoURLs=[], audioURL=null, audioName='', audioEl=new Audio();
let current=0, playing=false, exporting=false, started=0, raf=0, recorder=null, mic=null, voiceRec=null, dictation=null;
let audioContext=null, audioSource=null, audioDest=null, wakeLock=null, result=null, resultURL=null;
let exportAborted=false, prepared=[], preparedKey='';
const duration=()=>Number($('duration').value);
const fmt=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const status=t=>$('status').textContent=t;
function project(){const p={version:2,script:$('script').value,bars:$('bars').checked};settings.forEach(k=>p[k]=$(k).value);return p;}
function persist(){try{localStorage.setItem('voiceframe',JSON.stringify(project()));}catch{}}
function countWords(){$('words').textContent=($('script').value.trim().match(/\S+/g)||[]).length+' words';persist();}
function codecs(kind){if(!window.MediaRecorder)return [];return (kind==='mp4'?['video/mp4;codecs=avc1.640028,mp4a.40.2','video/mp4;codecs=avc1.42E028,mp4a.40.2','video/mp4;codecs=avc1.640028','video/mp4;codecs=avc1.42E028']:['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm']).filter(t=>MediaRecorder.isTypeSupported(t));}
function codecNotice(){const mp4=codecs('mp4').length>0;$('fileformat').querySelector('[value="mp4"]').disabled=!mp4;if(!mp4&&$('fileformat').value==='mp4')$('fileformat').value='webm';$('codecinfo').textContent=mp4?'MP4 / H.264 recording is available in this browser.':'This browser cannot record H.264 MP4. WebM is available; use an MP4-capable browser for wider social compatibility.';}
function configure(){const n=Number($('quality').value),r=$('ratio').value;[canvas.width,canvas.height]=r==='portrait'?[n,Math.round(n*16/9)]:r==='square'?[n,n]:[Math.round(n*16/9),n];$('formatlabel').textContent=`${canvas.width} × ${canvas.height} · 30 fps`;$('exportsummary').textContent=`${n}p · ${$('fileformat').value.toUpperCase()} · 30 fps · no watermark`;$('seek').max=duration();$('total').textContent=fmt(duration());preparedKey='';}
function paragraphs(){return $('script').value.trim().split(/\n\s*\n/).filter(Boolean).flatMap(p=>{const words=p.trim().split(/\s+/),out=[];let part='';for(const word of words){if(part.length+word.length>180&&part){out.push(part);part='';}part+=(part?' ':'')+word;}if(part)out.push(part);return out;});}
function build(){if(exporting)return;const parts=paragraphs();if(!parts.length&&!photos.length){status('Add photos or write a script to create your sequence.');return;}stop();scenes=Array.from({length:Math.max(parts.length,photos.length)},(_,i)=>({text:parts[i]||'',photo:photos.length?i%photos.length:-1}));current=0;configure();renderScenes();draw(0);countWords();status(`${scenes.length} scenes ready · ${fmt(duration())}. Photo motion, colour grading and dissolves are included. Select a scene, then tap Edit caption.`);}
function renderScenes(){const box=$('scenes');box.replaceChildren();scenes.forEach((scene,i)=>{const b=document.createElement('button');b.className='scene';if(scene.photo>=0){const img=new Image();img.src=photoURLs[scene.photo];img.alt='Scene photo';b.append(img);}const n=document.createElement('small');n.textContent=`${String(i+1).padStart(2,'0')} / SCENE`;const title=document.createElement('strong');title.textContent=scene.text?scene.text.slice(0,55)+(scene.text.length>55?'…':''):`Photo ${scene.photo+1} · cinematic motion`;const time=document.createElement('span');time.textContent=`${fmt(i*duration()/scenes.length)} — ${fmt((i+1)*duration()/scenes.length)}`;b.append(n,title,time);b.onclick=()=>{if(exporting)return;stop();current=i*duration()/scenes.length;draw(current);};b.ondblclick=()=>{if(exporting)return;const t=prompt('Scene caption (leave blank for clean footage)',scene.text);if(t!==null){scene.text=t.trim();$('script').value=scenes.map(s=>s.text).join('\n\n');countWords();renderScenes();draw(current);}};box.append(b);});$('scenecount').textContent=scenes.length+' scenes';}
function prepareImages(){const key=`${canvas.width}:${canvas.height}:${$('theme').value}:${photos.length}`;if(key===preparedKey)return;prepared.forEach(p=>p.width=0);prepared=[];const max=Math.max(canvas.width,canvas.height)*1.25;for(const img of photos){const scale=Math.min(1,max/Math.max(img.width,img.height));const buf=document.createElement('canvas');buf.width=Math.max(1,Math.round(img.width*scale));buf.height=Math.max(1,Math.round(img.height*scale));const b=buf.getContext('2d');b.filter=grades[$('theme').value];b.drawImage(img,0,0,buf.width,buf.height);if($('theme').value==='ocean'){b.fillStyle='rgba(0,72,95,.13)';b.fillRect(0,0,buf.width,buf.height);}prepared.push(buf);}preparedKey=key;}
function paintImage(img,i,p){const w=canvas.width,h=canvas.height;const motion=$('motion').value==='auto'?['push','pan','pull'][i%3]:$('motion').value;const eased=p*p*(3-2*p);let z=motion==='push'?1.03+.15*eased:motion==='pull'?1.18-.15*eased:1.14;const scale=Math.max(w/img.width,h/img.height)*z,iw=img.width*scale,ih=img.height*scale;let x=(w-iw)/2,y=(h-ih)/2;if(motion==='pan'){x=(w-iw)*(.15+.7*eased);y=(h-ih)*(.4+.2*eased);}else{x+=(iw-w)*.1*(eased-.5);y+=(ih-h)*.1*(eased-.5);}ctx.drawImage(img,x,y,iw,ih);}
function wrap(text,width,font){ctx.font=font;const lines=[];let line='';for(const word of text.split(/\s+/)){if(ctx.measureText(line+(line?' ':'')+word).width>width&&line){lines.push(line);line='';}if(ctx.measureText(word).width>width){for(const ch of word){if(ctx.measureText(line+ch).width>width&&line){lines.push(line);line='';}line+=ch;}}else line+=(line?' ':'')+word;}if(line)lines.push(line);return lines;}
function caption(scene,p){if(!scene.text||$('captions').value==='none')return;const w=canvas.width,h=canvas.height,u=Math.min(w,h),center=$('captions').value==='center';let size=u*(center?.052:.038);let lines=wrap(scene.text,w*.8,`600 ${size}px sans-serif`);while(lines.length*size*1.4>h*(center?.65:.3)&&size>u*.018){size*=.9;lines=wrap(scene.text,w*.8,`600 ${size}px sans-serif`);}ctx.font=`600 ${size}px sans-serif`;const lh=size*1.4;const y=center?(h-lines.length*lh)/2:h*.8-lines.length*lh;ctx.save();ctx.globalAlpha=Math.min(1,p*10+.35);if(!center){const g=ctx.createLinearGradient(0,h*.45,0,h);g.addColorStop(0,'transparent');g.addColorStop(1,'rgba(0,0,0,.72)');ctx.fillStyle=g;ctx.fillRect(0,h*.45,w,h*.55);}ctx.shadowColor='#000';ctx.shadowBlur=size*.3;ctx.fillStyle='#fff';ctx.textBaseline='top';lines.forEach((l,n)=>ctx.fillText(l,w*.1,y+n*lh));ctx.restore();}
function paintScene(i,p,alpha=1){ctx.save();ctx.globalAlpha=alpha;const s=scenes[i],w=canvas.width,h=canvas.height;if(s?.photo>=0&&prepared[s.photo]){paintImage(prepared[s.photo],i,p);}else{const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,$('theme').value==='sunset'?'#573c30':'#11262b');g.addColorStop(1,$('theme').value==='sunset'?'#bf9670':'#486858');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);for(let n=0;n<6;n++){ctx.beginPath();ctx.arc(w*.8+Math.sin(p+n)*w*.16,h*.45+Math.cos(p+n)*h*.3,Math.min(w,h)*(.1+n*.045),0,Math.PI*2);ctx.strokeStyle='#ffffff16';ctx.lineWidth=2;ctx.stroke();}}const v=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,Math.max(w,h)*.7);v.addColorStop(.25,'transparent');v.addColorStop(1,'rgba(0,0,0,.35)');ctx.fillStyle=v;ctx.fillRect(0,0,w,h);caption(s,p);ctx.restore();}
function draw(t,updateUI=true){prepareImages();const w=canvas.width,h=canvas.height;ctx.fillStyle='#101819';ctx.fillRect(0,0,w,h);let i=0;if(scenes.length){const d=duration()/scenes.length;i=Math.min(scenes.length-1,Math.floor(t/d));const elapsed=Math.min(d,t-i*d),p=Math.min(1,elapsed/d),fade=Math.min(.8,d*.2);if(i>0&&elapsed<fade){paintScene(i-1,1);paintScene(i,p,elapsed/fade);}else paintScene(i,p);if($('bars').checked){ctx.fillStyle='#000';ctx.fillRect(0,0,w,h*.075);ctx.fillRect(0,h*.925,w,h*.075);}}else{ctx.fillStyle='#bddd9a';ctx.font=`500 ${Math.min(w,h)*.05}px sans-serif`;ctx.fillText('Your next film starts here.',w*.1,h*.48);ctx.fillStyle='#a4b2b5';ctx.font=`400 ${Math.min(w,h)*.026}px sans-serif`;ctx.fillText('Add photos. Set the mood. Press create.',w*.1,h*.57);}if(updateUI){$('time').textContent=fmt(t);$('seek').value=t;[...$('scenes').children].forEach((b,n)=>b.classList.toggle('selected',i===n));}}
function stop(){playing=false;cancelAnimationFrame(raf);audioEl.pause();$('play').textContent='▶';}
function tick(now){current=Math.min(duration(),(now-started)/1000);draw(current);if(exporting)$('progress').value=current/duration()*100;if(current>=duration()){stop();if(exporting&&recorder.state!=='inactive')recorder.stop();return;}raf=requestAnimationFrame(tick);}
async function play(){if(!scenes.length){status('Create your sequence first.');return;}if(playing){stop();return;}if(current>=duration())current=0;if(audioURL){audioEl.currentTime=Math.min(current,Number.isFinite(audioEl.duration)?audioEl.duration:current);try{await audioEl.play();}catch{status('Audio could not play. Check your audio format.');}}playing=true;$('play').textContent='Ⅱ';started=performance.now()-current*1000;raf=requestAnimationFrame(tick);}
function releasePhotos(){photos.forEach(p=>p.close?.());photos=[];photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];preparedKey='';}
function assetStrip(){const box=$('assets');box.replaceChildren();photoURLs.forEach((u,i)=>{const im=new Image();im.src=u;im.alt='Uploaded photo '+(i+1);box.append(im);});$('imagecount').textContent=photos.length?`(${photos.length})`:'';$('removephotos').hidden=!photos.length;}
async function loadPhotos(files){let ims=[],urls=[];try{if(files.length>60)throw Error('Please use at most 60 photos per project.');for(const file of files){ims.push(await createImageBitmap(file));urls.push(URL.createObjectURL(file));}releasePhotos();photos=ims;photoURLs=urls;assetStrip();build();}catch(e){ims.forEach(x=>x.close?.());urls.forEach(URL.revokeObjectURL);status('Could not load photos: '+e.message);}}
function setAudio(blob,name){$('matchaudio').hidden=false;stop();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(blob);audioName=name;audioEl.src=audioURL;$('audioname').textContent=name+' · attached';$('removeaudio').hidden=false;}
function lock(on){document.querySelectorAll('button,input,textarea,select').forEach(el=>{if(el.id!=='cancel')el.disabled=on;});$('cancel').hidden=!on;$('progress').hidden=!on;if(!on)codecNotice();}
async function releaseWake(){if(wakeLock){try{await wakeLock.release();}catch{}wakeLock=null;}}
async function recordVideo(){if(!scenes.length){status('Create your sequence first.');return;}if(!window.MediaRecorder||!canvas.captureStream){status('Video recording is not available in this browser. Use desktop Chrome or Edge.');return;}if(voiceRec?.state==='recording'){status('Stop narration recording first.');return;}if(dictation)dictation.stop();window.speechSynthesis?.cancel();stop();current=0;configure();draw(0);const type=codecs($('fileformat').value)[0];if(!type){status('This browser cannot record the selected format. Select WebM or try another browser.');return;}let stream;exportAborted=false;try{stream=canvas.captureStream(30);if(audioURL){audioContext||=new AudioContext({sampleRate:48000});await audioContext.resume();if(!audioSource){audioSource=audioContext.createMediaElementSource(audioEl);audioDest=audioContext.createMediaStreamDestination();audioSource.connect(audioDest);audioSource.connect(audioContext.destination);}audioDest.stream.getAudioTracks().forEach(t=>stream.addTrack(t));audioEl.currentTime=0;await audioEl.play();}const chunks=[];const isMP4=type.startsWith('video/mp4');const bitrate=$('quality').value==='1080'?8000000:5000000;recorder=new MediaRecorder(stream,{mimeType:type,videoBitsPerSecond:bitrate,audioBitsPerSecond:192000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>{exportAborted=true;status('The browser could not encode this video. Try 720p or WebM.');if(recorder.state!=='inactive')recorder.stop();else cleanup();};const cleanup=()=>{stop();exporting=false;lock(false);stream.getVideoTracks().forEach(t=>t.stop());releaseWake();};recorder.onstop=()=>{cleanup();if(exportAborted)return;if(!chunks.length){status('No video data was recorded. Try another format.');return;}result=new File(chunks,`VoiceFrame-${$('quality').value}p.${isMP4?'mp4':'webm'}`,{type:recorder.mimeType||type});if(resultURL)URL.revokeObjectURL(resultURL);resultURL=URL.createObjectURL(result);const a=document.createElement('a');a.href=resultURL;a.download=result.name;a.className='btn primary';a.textContent=`↓ Download ${isMP4?'MP4':'WebM'} · ${(result.size/1024/1024).toFixed(1)} MB`;const note=document.createElement('span');note.className='hint';note.textContent=`${canvas.width} × ${canvas.height} · target 30 fps · ${(bitrate/1000000).toFixed(0)} Mbps · ${fmt(duration())}`;$('download').replaceChildren(a,note);$('share').hidden=!(navigator.canShare&&navigator.canShare({files:[result]}));status('Your video is ready. Download it, then upload it to your channel or social account. Use only photos and audio you own or have licensed.');};exporting=true;lock(true);$('download').replaceChildren();$('share').hidden=true;$('progress').value=0;recorder.start(1000);playing=true;started=performance.now();raf=requestAnimationFrame(tick);status(`Rendering ${$('quality').value}p ${isMP4?'MP4':'WebM'} in real time. Keep this tab visible; about ${fmt(duration())} to complete.`);if(navigator.wakeLock){navigator.wakeLock.request('screen').then(l=>wakeLock=l).catch(()=>{});}}catch(e){stop();exporting=false;lock(false);stream?.getVideoTracks().forEach(t=>t.stop());releaseWake();status('Could not export: '+e.message);}}
$('editcaption').onclick=()=>{if(!scenes.length){status('Create a sequence first.');return;}stop();const i=Math.min(scenes.length-1,Math.floor(current/duration()*scenes.length));const text=prompt('Edit scene '+(i+1)+' caption (blank for no caption)',scenes[i].text);if(text!==null){scenes[i].text=text.trim();$('script').value=scenes.map(s=>s.text).join('\n\n');countWords();renderScenes();draw(current);}};
$('generate').onclick=build;$('script').oninput=countWords;$('play').onclick=play;
$('seek').oninput=()=>{if(exporting)return;stop();current=Number($('seek').value);draw(current);};
settings.forEach(k=>$(k).onchange=()=>{configure();stop();current=0;renderScenes();draw(0);persist();});
$('bars').onchange=()=>{draw(current);persist();};
$('images').onchange=e=>loadPhotos([...e.target.files]);
$('removephotos').onclick=()=>{releasePhotos();assetStrip();$('images').value='';if($('script').value.trim())build();else{scenes=[];renderScenes();draw(0);status('Photos cleared. Add your own photos to begin.');}};
$('audiofile').onchange=e=>{if(e.target.files[0])setAudio(e.target.files[0],e.target.files[0].name);};
$('removeaudio').onclick=()=>{stop();URL.revokeObjectURL(audioURL);audioURL=null;audioName='';audioEl.removeAttribute('src');audioEl.load();$('audiofile').value='';$('audioname').textContent='No audio attached · export will be silent';$('removeaudio').hidden=true;$('matchaudio').hidden=true;};
$('texttab').onclick=()=>{$('voicebox').style.display='none';$('texttab').classList.add('active');$('voicetab').classList.remove('active');};
$('voicetab').onclick=()=>{$('voicebox').style.display='block';$('voicetab').classList.add('active');$('texttab').classList.remove('active');};
$('dictate').onclick=()=>{if(dictation){dictation.stop();return;}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){status('Dictation is unavailable here. Type a script or try Chrome / Edge.');return;}dictation=new Speech();dictation.lang=$('language').value;dictation.continuous=true;dictation.interimResults=false;dictation.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)$('script').value+=' '+e.results[i][0].transcript;countWords();};dictation.onerror=e=>status('Dictation: '+e.error+'. You can still type your script.');dictation.onend=()=>{dictation=null;$('dictate').textContent='Start dictation';};try{dictation.start();$('dictate').textContent='Stop dictation';}catch(e){dictation=null;status(e.message);}};
$('record').onclick=async()=>{if(voiceRec?.state==='recording'){voiceRec.stop();return;}try{mic=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];voiceRec=new MediaRecorder(mic);voiceRec.ondataavailable=e=>chunks.push(e.data);voiceRec.onstop=()=>{setAudio(new Blob(chunks,{type:voiceRec.mimeType}),'Recorded narration');mic.getTracks().forEach(t=>t.stop());$('record').textContent='Record narration';clearTimeout(voiceRec.limit);};voiceRec.start();voiceRec.limit=setTimeout(()=>{if(voiceRec.state==='recording')voiceRec.stop();},600000);$('record').textContent='Stop recording';status('Recording narration · press Stop recording when finished. Maximum 10 minutes.');}catch(e){mic?.getTracks().forEach(t=>t.stop());status('Microphone unavailable: '+e.message);}};
async function exportVideo(){
 if(!scenes.length){status('Create your sequence first.');return;}
 if(voiceRec?.state==='recording'){status('Stop narration recording first.');return;}
 if(!window.VideoEncoder){await recordVideo();return;}
 stop();window.speechSynthesis?.cancel();if(dictation)dictation.stop();
 exportAborted=false;exporting=true;lock(true);$('download').replaceChildren();$('share').hidden=true;$('progress').value=0;
 configure();draw(0);
 let handedOff=false;
 const fileformat=$('fileformat').value, bitrate=$('quality').value==='1080'?8000000:5000000;
 status('Encoding every frame at 30 fps. Render time depends on your device; keep this tab open.');
 try {
  let buffer=null;
  if(audioURL){audioContext||=new AudioContext({sampleRate:48000});const original=await audioContext.decodeAudioData(await (await fetch(audioURL)).arrayBuffer());
   const count=Math.min(original.length,Math.round(duration()*original.sampleRate));
   buffer=audioContext.createBuffer(Math.min(2,original.numberOfChannels),count,original.sampleRate);
   for(let n=0;n<buffer.numberOfChannels;n++)buffer.copyToChannel(original.getChannelData(n).subarray(0,count),n);
  }
  const encoded=await renderOffline({canvas,seconds:duration(),format:fileformat,bitrate,audioBuffer:buffer,draw:t=>{current=t;draw(t,false);},onProgress:p=>{$('progress').value=p;$('time').textContent=fmt(current);$('seek').value=current;},aborted:()=>exportAborted});
  if(encoded===null){exporting=false;lock(false);handedOff=true;await recordVideo();return;}
  if(encoded.cancelled||exportAborted){status('Export cancelled. Your photos and sequence are still available.');return;}
  result=new File([encoded.blob],`VoiceFrame-${$('quality').value}p.${fileformat}`,{type:encoded.blob.type});
  if(resultURL)URL.revokeObjectURL(resultURL);resultURL=URL.createObjectURL(result);
  const link=document.createElement('a');link.href=resultURL;link.download=result.name;link.className='btn primary';link.textContent=`↓ Download ${fileformat.toUpperCase()} · ${(result.size/1024/1024).toFixed(1)} MB`;
  const note=document.createElement('span');note.className='hint';note.textContent=`${canvas.width} × ${canvas.height} · 30 fps · ${fmt(duration())}`;
  $('download').replaceChildren(link,note);$('share').hidden=!(navigator.canShare&&navigator.canShare({files:[result]}));current=duration();draw(current);
  status('Your video is ready. Download it, then upload it to your channel or social account. Use only photos and audio you own or have licensed.');
 }catch(e){if(!exportAborted)status('Encoding failed: '+e.message+'. Try WebM or a lower resolution.');}
 finally{if(!handedOff){exporting=false;lock(false);}}
}
$('export').onclick=exportVideo;
$('cancel').onclick=()=>{exportAborted=true;stop();if(recorder && recorder.state!=='inactive')recorder.stop();status('Export cancelled. Your photos and sequence are still available.');};
$('speak').onclick=()=>{if(!window.speechSynthesis){status('Speech preview is unavailable here.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance($('script').value);u.lang=$('language').value;speechSynthesis.speak(u);};
$('stopspeak').onclick=()=>window.speechSynthesis?.cancel();
$('share').onclick=async()=>{if(!result)return;try{await navigator.share({files:[result],title:'My VoiceFrame film'});}catch(e){if(e.name!=='AbortError')status('Sharing is unavailable. Download the video and upload it from your social app.');}};
function restore(p){if(typeof p.script!=='string')throw Error('Invalid project');$('script').value=p.script;const allowed={duration:['10','30','60','180','300','600'],ratio:['landscape','portrait','square'],quality:['1080','720'],theme:Object.keys(grades),motion:['auto','push','pull','pan'],captions:['lower','none','center'],fileformat:['mp4','webm']};for(const k of settings){if(p[k]!==undefined){if(k==='duration'&&Number(p[k])>0&&Number(p[k])<=600){if(![...$('duration').options].some(o=>o.value===String(p[k]))){const option=new Option('Audio match · '+fmt(Number(p[k])),String(p[k]));$('duration').add(option);}}else if(!allowed[k].includes(String(p[k])))throw Error('Invalid '+k);$(k).value=String(p[k]);}}$('bars').checked=!!p.bars;codecNotice();}
$('save').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(project(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='VoiceFrame-project.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status('Project saved. Reattach your original photos and audio after import.');};
$('import').onchange=async e=>{try{const p=JSON.parse(await e.target.files[0].text());restore(p);configure();build();}catch{status('Invalid project JSON. Choose a project exported by VoiceFrame.');}};
$('sample').onclick=async()=>{stop();try{const names=['demo-mountains.svg','demo-coast.svg','demo-dunes.svg'];const blobs=await Promise.all(names.map(async n=>{const r=await fetch(n);if(!r.ok)throw Error('Demo could not load');return new File([await r.blob()],n,{type:'image/svg+xml'});}));const images=await Promise.all(blobs.map(blob=>new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(blob);img.onload=()=>{URL.revokeObjectURL(url);resolve(img);};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Demo image could not load'));};img.src=url;})));releasePhotos();photos=images;photoURLs=blobs.map(URL.createObjectURL);$('script').value='The world feels different when you slow down.\n\nFollow the light. Let the journey unfold.\n\nMake a moment worth remembering.';$('duration').value='10';assetStrip();build();status('Original landscape illustrations demo loaded. Replace these with your own photos for a photographic film.');}catch(e){status(e.message);}};
try{const saved=JSON.parse(localStorage.getItem('voiceframe'));if(saved)restore(saved);}catch{}
codecNotice();configure();countWords();if($('script').value.trim())build();else draw(0);
window.addEventListener('beforeunload',e=>{if(exporting||voiceRec?.state==='recording'){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(exporting&&document.hidden)status('This tab is hidden. Return to it now to avoid dropped frames during rendering.');});

function engineDialog(kind){const avatar=kind==='avatar';$('engine-title').textContent=avatar?'Create a realistic AI avatar':'Generate a realistic AI voice';$('engine-copy').textContent=avatar?'Talking avatars, character animation and lip-sync are not installed in this photo studio. An AI rendering engine is needed before your photo can become a speaking character. You can currently turn your photos into a cinematic film.':'AI narration and voice cloning are not connected. You can record your own voice or upload an audio file for export. Listen to script uses your device’s voice for preview only and is not included in downloads.';const d=$('engine-dialog');if(d.showModal)d.showModal();else alert($('engine-copy').textContent);}
$('avatarmode').onclick=()=>engineDialog('avatar');$('avatarnav').onclick=()=>engineDialog('avatar');$('voicemode').onclick=()=>engineDialog('voice');$('voicenav').onclick=()=>engineDialog('voice');$('close-dialog').onclick=()=>$('engine-dialog').close();
$('photomode').onclick=()=>$('create').scrollIntoView({behavior:'smooth'});
$('savequick').onclick=()=>$('save').click();$('projectnav').onclick=()=>$('save').click();$('demoquick').onclick=()=>$('sample').click();
$('matchaudio').onclick=async()=>{if(!audioURL)return;try{if(!Number.isFinite(audioEl.duration)){await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Audio metadata unavailable. Try a WAV or MP3 file.')),8000);audioEl.addEventListener('loadedmetadata',()=>{clearTimeout(timer);resolve();},{once:true});audioEl.addEventListener('error',()=>{clearTimeout(timer);reject(Error('Could not read this audio file.'));},{once:true});});}const seconds=Math.ceil(audioEl.duration*1000)/1000;if(!Number.isFinite(seconds)||seconds<=0||seconds>600)throw Error('Use an audio file between 1 second and 10 minutes.');const old=$('duration').querySelector('[data-audio]');old?.remove();const option=new Option('Audio match · '+fmt(seconds),String(seconds));option.dataset.audio='true';$('duration').add(option);$('duration').value=String(seconds);configure();stop();current=0;renderScenes();draw(0);persist();status('Video runtime matched to your audio: '+seconds.toFixed(2)+' seconds. This aligns total length, not individual words or mouth movements.');}catch(e){status(e.message);}};
window.addEventListener('error',e=>status('The studio encountered a problem: '+e.message+'. Reload the page and try a 10-second 720p export.'));
window.addEventListener('unhandledrejection',e=>status('Action failed: '+(e.reason?.message||'Unknown error')+'. Try again or use 720p / WebM.'));
